    "content": " // serveUserAvatar serves user avatar images. func (s *FileServerService) serveUserAvatar(c *echo.Context) error { ctx := c.Request().Context() // On a private instance (no InstanceURL), avatars are not exposed to anonymous // visitors; a valid session, access token, or PAT is required. if !s.Profile.AllowAnonymous() { viewer, err := s.getCurrentUser(ctx, c) if err != nil { return echo.NewHTTPError(http.StatusInternalServerError, \"failed to get current user\").Wrap(err) } if viewer == nil { return echo.NewHTTPError(http.StatusUnauthorized, \"unauthorized access\") } } identifier := c.Param(\"identifier\") user, err := s.getUserByUsername(ctx, identifier) if err != nil { return echo.NewHTTPError(http.StatusInternalServerError, \"failed to get user\").Wrap(err) } if user == nil { return echo.NewHTTPError(http.StatusNotFound, \"user not found\") } if user.AvatarURL == \"\" { return echo.NewHTTPError(http.StatusNotFound, \"avatar not found\") } imageType, imageData, err := s.parseDataURI(user.AvatarURL) if err != nil { return echo.NewHTTPError(http.StatusInternalServerError, \"failed to parse avatar data\").Wrap(err) } if !avatarAllowedTypes[imageType] { return echo.NewHTTPError(http.StatusBadRequest, \"invalid avatar image type\") } setSecurityHeaders(c) c.Response().Header().Set(echo.HeaderContentType, imageType) c.Response().Header().Set(echo.HeaderCacheControl, cacheMaxAge) return c.Blob(http.StatusOK, imageType, imageData) } // ============================================================================="
  },
